// Basic Aliasing Syntax Comparison

// Traditional C++ Syntax
typedef unsigned int UInt;
typedef std::vector<std::string> StringList;

// Modern C++ Syntax (Preferred)
using Byte = unsigned char;
using Point = std::pair<double, double>;

// Aliasing a function pointer (using is cleaner)
typedef bool (*Validator)(int);
using Processor = void (*)(const std::string&);


// Template Aliases (Only possible with 'using')

template <typename T>
class Cache {};

// 'typedef' cannot be used for template aliases.

template <typename T>
using SharedCache = std::shared_ptr<Cache<T>>;

template <typename T>
using Matrix = std::array<T, 4>;

SharedCache<int> int_cache;
Matrix<float> mat;
